import json, csv
from pathlib import Path
# load input
with open('input/nodes.csv', newline='', encoding='utf-8') as f:
    in_nodes=list(csv.DictReader(f))
with open('input/edges.csv', newline='', encoding='utf-8') as f:
    in_edges=list(csv.DictReader(f))
# load output
with open('output/graph.json', encoding='utf-8') as f:
    out=json.load(f)
# checks
errs=[]
if len(out.get('nodes',[]))!=len(in_nodes): errs.append(f'nodes count {len(out.get("nodes",[]))}!={len(in_nodes)}')
if len(out.get('edges',[]))!=len(in_edges): errs.append(f'edges count {len(out.get("edges",[]))}!={len(in_edges)}')
# exact inclusion as ordered lists mapped
for i,(inn,outn) in enumerate(zip(in_nodes,out.get('nodes',[]))):
    exp={'id':inn['id'],'speaker':inn['speaker'],'text':inn['text'],'type':inn['type']}
    if outn!=exp: errs.append(f'node {i} mismatch {outn} != {exp}')
for i,(ine,oute) in enumerate(zip(in_edges,out.get('edges',[]))):
    exp={'from':ine['source'],'to':ine['target'],'text':ine['text']}
    if oute!=exp: errs.append(f'edge {i} mismatch {oute} != {exp}')
print('ERRORS' if errs else 'OK')
for e in errs: print(e)
